/* @lc app=leetcode id=3855 lang=kotlin */ class Solution { fun sumOfNumbers(l: Int, r: Int, k: Int): Int = 1_000_000_007L.let { M -> java.math.BigInteger.valueOf(M).let { bm -> ((l + r) * (r - l + 1) / 2).toLong().let { S -> (r - l + 1).toLong().let { d -> (S % M * java.math.BigInteger.valueOf(d).modPow(java.math.BigInteger.valueOf(k - 1L), bm).toLong() % M * ((java.math.BigInteger.TEN.modPow(java.math.BigInteger.valueOf(k.toLong()), bm).toLong() - 1 + M) % M * 111111112L % M) % M).toInt() } } } } }